//! Bit-exact conformance against the Python reference.
//! `golden.txt` is generated by `tools/neuro-research/gen_golden.py` from `dna_fixed.py`; see that file for
//! the line format. Run with: `cargo test --release` in `os/neuro/neuro-core` (host target).

use neuro_core::*;

fn hex64(s: &str) -> u64 {
    u64::from_str_radix(s, 16).unwrap()
}
fn hex32(s: &str) -> u32 {
    u32::from_str_radix(s, 16).unwrap()
}

#[test]
fn golden_vectors() {
    let text = include_str!("golden.txt");
    let mut dna = [Dna::new(); 3];
    let mut agg = [HourAgg::new(); 3];
    let (mut closes, mut alarms, mut checks) = (0usize, 0usize, 0usize);
    for (ln, line) in text.lines().enumerate() {
        let t: Vec<&str> = line.split_whitespace().collect();
        if t.is_empty() {
            continue;
        }
        let at = |i: usize| t[i].parse::<i64>().unwrap();
        match t[0] {
            "S" => {
                assert_eq!(splitmix64(hex64(t[1])), hex64(t[2]), "line {}: splitmix64", ln + 1);
                checks += 1;
            }
            "L" => {
                assert_eq!(log2_q8(t[1].parse::<u64>().unwrap()), at(2), "line {}: log2_q8", ln + 1);
                checks += 1;
            }
            "P" => {
                let fp = fingerprint(peer_key(hex32(t[1]), t[2].parse::<u16>().unwrap()));
                assert_eq!(fp, hex32(t[3]), "line {}: fingerprint", ln + 1);
                checks += 1;
            }
            "R" => {
                let d = at(1) as usize;
                dna[d] = Dna::new();
                agg[d].reset();
            }
            "F" => {
                let d = at(1) as usize;
                let (m, a) = (&dna[d], &mut agg[d]);
                a.add_flow(m, Some(hex32(t[2])), t[3].parse().unwrap(), t[4].parse().unwrap());
            }
            "N" => {
                let d = at(1) as usize;
                let (m, a) = (&dna[d], &mut agg[d]);
                a.add_flow(m, None, t[2].parse().unwrap(), t[3].parse().unwrap());
            }
            "D" => {
                let d = at(1) as usize;
                let (m, a) = (&dna[d], &mut agg[d]);
                a.add_dns(m, hex32(t[2]), t[3] == "1");
            }
            "C" => {
                let d = at(1) as usize;
                let s = dna[d].close_hour(at(2) as usize, &agg[d]);
                agg[d].reset();
                let want = Score { score: at(3), vol: at(4), fan: at(5), novel: at(6), dns: at(7), act: at(8) };
                assert_eq!(s, want, "line {}: hour close dev {} hr {}", ln + 1, d, at(2));
                closes += 1;
                alarms += (s.score >= CALM_Q8) as usize;
            }
            "X" => {
                let d = at(1) as usize;
                let groups: Vec<Vec<i64>> = line[2..]
                    .split('|')
                    .map(|g| g.split_whitespace().map(|v| v.parse().unwrap()).collect())
                    .collect();
                let m = &dna[d];
                let first: Vec<i64> = groups[0][1..].to_vec(); // groups[0] starts with the device id
                assert_eq!(first, m.act.map(|v| v as i64).to_vec(), "dev {} act", d);
                assert_eq!(groups[1], m.bmu.map(|v| v as i64).to_vec(), "dev {} bmu", d);
                assert_eq!(groups[2], m.bdev.map(|v| v as i64).to_vec(), "dev {} bdev", d);
                assert_eq!(groups[3], m.fmu.map(|v| v as i64).to_vec(), "dev {} fmu", d);
                assert_eq!(groups[4], m.fdev.map(|v| v as i64).to_vec(), "dev {} fdev", d);
                assert_eq!(groups[5], m.n.map(|v| v as i64).to_vec(), "dev {} n", d);
                let tail = &groups[6];
                assert_eq!(tail[0], m.nx as i64, "dev {} nx", d);
                assert_eq!(tail[1], m.nov_mu as i64, "dev {} nov_mu", d);
                assert_eq!(tail[2], m.nov_dev as i64, "dev {} nov_dev", d);
                assert_eq!(tail[3..].to_vec(), m.p.map(|v| v as i64).to_vec(), "dev {} pooled", d);
                checks += 1;
            }
            other => panic!("line {}: unknown record {}", ln + 1, other),
        }
    }
    assert_eq!(closes, 1200, "every generated hour was checked");
    println!(
        "golden: {} hour closes ({} alarms) bit-exact, {} unit checks; {} B per device",
        closes,
        alarms,
        checks,
        bytes_per_device()
    );
}

#[test]
fn driver_names_the_largest_part() {
    let s = Score { score: 900, vol: 10, fan: 900, novel: 3, dns: 0, act: 0 };
    assert_eq!(s.driver(), Driver::FanOut);
}
